// A content mapper for tsgolint's tests, speaking the TypeScript 7 content mapper protocol
// (JSON-RPC over stdio with LSP Content-Length framing) with no dependencies.
//
// It transforms a `.ext` file into TypeScript that reproduces the three mapping shapes a real mapper
// produces, each carrying code a type-aware rule fires on:
//
//   const __scaffold__ = JSON.parse("{}");   no mapping at all: a diagnostic here maps with no fidelity
//   __scaffold__.trailing();                 mapped onto a zero-length original range
//   <file content>                           copied verbatim
//
// The zero-length shape is what a mapper emits when it cannot express an original range that strictly
// contains another; ember-content-mapper does this in demoteOverlappingOriginals.

const KIND_VERBATIM = 0;
const KIND_ATOM = 1;
const FEATURE_ALL = (1 << 20) - 1;

const PROLOGUE = 'const __scaffold__ = JSON.parse("{}");\n';
const ANCHOR = '__scaffold__.trailing();\n';

// A marker in the input that makes the mapper report a diagnostic of its own against it. A mapper's
// diagnostics are expressed in original offsets, unlike everything else the compiler produces for the
// file, so they must not be mapped a second time.
const MARKER = '@@mapper-error@@';

function transform({ content }) {
  const result = {
    text: PROLOGUE + ANCHOR + content,
    extension: '.ts',
    mappings: [
      [PROLOGUE.length, ANCHOR.length, 0, 0, KIND_ATOM, 0],
      [PROLOGUE.length + ANCHOR.length, content.length, 0, content.length, KIND_VERBATIM, FEATURE_ALL],
    ],
  };

  const marker = content.indexOf(MARKER);
  if (marker !== -1) {
    result.diagnostics = [{ messageText: 'test mapper syntax error', start: marker, length: MARKER.length }];
  }

  return result;
}

const handlers = {
  initialize: () => ({
    protocolVersion: 1,
    positionEncoding: 'utf-8',
    diagnosticSource: 'test-content-mapper',
  }),
  openProject: () => ({}),
  transform,
  closeProject: () => null,
};

let buffer = Buffer.alloc(0);

function write(message) {
  const payload = Buffer.from(JSON.stringify(message), 'utf8');
  process.stdout.write(`Content-Length: ${payload.length}\r\n\r\n`);
  process.stdout.write(payload);
}

process.stdin.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  for (;;) {
    const headerEnd = buffer.indexOf('\r\n\r\n');
    if (headerEnd === -1) return;
    const header = buffer.subarray(0, headerEnd).toString('ascii');
    const length = Number(/content-length: *(\d+)/i.exec(header)?.[1]);
    const bodyStart = headerEnd + 4;
    if (!Number.isFinite(length) || buffer.length < bodyStart + length) return;
    const message = JSON.parse(buffer.subarray(bodyStart, bodyStart + length).toString('utf8'));
    buffer = buffer.subarray(bodyStart + length);
    if (message.id === undefined) continue;
    const handler = handlers[message.method];
    if (!handler) {
      write({ jsonrpc: '2.0', id: message.id, error: { code: -32601, message: 'unknown method' } });
      continue;
    }
    write({ jsonrpc: '2.0', id: message.id, result: handler(message.params ?? {}) });
  }
});
